// DDL 생성(순수, PRD_PiErd S2 P6) — 저장된 물리 모델 → PostgreSQL·Oracle·Tibero CREATE TABLE·PK·COMMENT·FK 스크립트(.sql 내려받기만, DB 직접 실행 없음)
// FK : PostgreSQL = ALTER TABLE ADD CONSTRAINT, Oracle·Tibero = 주석으로만(DBMS 프로파일 STD-08 물리 FK 미생성). 칼럼 쌍 = 자식 칼럼 속성의 원천(src_attr_id) → 부모 칼럼
// 시스템 칼럼 4개(phy.ts sysCols)는 여기서만 테이블 맨 끝에 추가 — 모델·정의서·ERD 에는 없음
// ponytail: 변경일시 갱신 트리거·인덱스(PK 외)·ALTER 변경분은 미생성 — 인덱스 설계·변경분 DDL 은 S5
// 자동 증가(마스터 지시 2026-10-18, 테이블별 옵션 mdl_phy_tbl.auto_inc_yn — sql/036) : 단일 정수 PK(소수점 없음·관계 상속 아님) → PostgreSQL INTEGER·BIGINT / Oracle NUMBER GENERATED BY DEFAULT AS IDENTITY,
//  Tibero 는 IDENTITY 지원 미확인이라 CREATE SEQUENCE(입력 때 NEXTVAL). BY DEFAULT = 이행 때 기존 값 그대로 넣을 수 있음. 다른 DBMS 문법은 AUTO_INC 참고(MySQL·MS-SQL 프로파일 추가 때 사용)
import { DBMS_PRFL, type DbmsCd } from './dbms.ts'
import { bscOk, pkName, RSV_WORDS, sysCols, type PhyCol } from './phy.ts'
import type { DocTable } from './docs.ts'

export interface DdlTbl {
  ent_id: string
  tbl_nm: string
  tbl_desc: string | null
  auto_inc_yn?: 'Y' | 'N' // 단일 PK 자동 증가(테이블별, sql/036)
  cols: (PhyCol & { col_desc?: string | null })[]
}
export interface DdlFk {
  rel_id: string
  fk_nm: string
  prnt_ent_id: string
  chld_ent_id: string
}
export interface DdlIn {
  dbms: DbmsCd
  ltr: 'UPPER' | 'LOWER'
  tables: DdlTbl[]
  fks: DdlFk[]
  src: Map<string, string | null> // 자식 속성ID → 원천 부모 속성ID(src_attr_id)
  fkOf: Map<string, string | null> // 속성ID → 상속 관계ID(fk_rel_id)
}

const q = (s: string) => `'${s.replace(/'/g, "''")}'`
// 주석 줄(-- …)에 넣는 자유 텍스트 — 줄바꿈 등 제어문자를 공백으로(주석 탈출 → 임의 SQL 삽입 차단)
const line1 = (s: string) => s.replace(/[\p{Cc}\p{Zl}\p{Zp}]/gu, ' ') // 제어문자(0~1F·7F~9F)·줄/문단 구분자
// 자동 증가 문법(참고 포함) — MySQL AUTO_INCREMENT·MS-SQL IDENTITY(1,1) 는 DBMS 프로파일 추가 때 사용
export const AUTO_INC = { pg: 'GENERATED BY DEFAULT AS IDENTITY', ora: 'GENERATED BY DEFAULT AS IDENTITY', mysql: 'AUTO_INCREMENT', mssql: 'IDENTITY(1,1)' } as const
const INT_TP = /^(NUMBER|NUMERIC|DECIMAL|INT|INTEGER|BIGINT|SMALLINT)$/i
// 자동 증가 대상 칼럼 — PK 칼럼이 하나, 정수형(소수점 없음), 관계 상속(FK) 칼럼이 아님. 아니면 null
export function autoIncCol(t: DdlTbl, fkOf?: Map<string, string | null>): PhyCol | null {
  const pk = t.cols.filter((c) => c.pk_yn === 'Y')
  if (pk.length !== 1) return null
  const c = pk[0]
  if (c.attr_id && fkOf?.get(c.attr_id)) return null
  return INT_TP.test(c.phy_tp_nm) && !(c.data_scale ?? 0) ? c : null
}
const tpOf = (c: PhyCol) => (c.data_len != null ? `${c.phy_tp_nm}(${c.data_len}${c.data_scale != null ? `,${c.data_scale}` : ''})` : c.phy_tp_nm)

// FK 칼럼 쌍 — 원천 우선, 없으면 부모 PK 중 같은 칼럼명
export function fkPairs(fk: DdlFk, byEnt: Map<string, DdlTbl>, d: Pick<DdlIn, 'src' | 'fkOf'>): [string, string][] {
  const c = byEnt.get(fk.chld_ent_id)
  const p = byEnt.get(fk.prnt_ent_id)
  if (!c || !p) return []
  const pk = p.cols.filter((x) => x.pk_yn === 'Y')
  return c.cols
    .filter((x) => x.attr_id && d.fkOf.get(x.attr_id) === fk.rel_id)
    .map((x): [string, string] | null => {
      const s = d.src.get(x.attr_id!)
      const pc = pk.find((y) => (s ? y.attr_id === s : y.col_nm === x.col_nm))
      return pc ? [x.col_nm, pc.col_nm] : null
    })
    .filter((v): v is [string, string] => !!v)
}

// opt.only(엔터티ID, DDL 생성 화면) : 선택 테이블만 CREATE·COMMENT, FK 는 부모·자식 모두 선택일 때만(자식만 선택이면 보류 주석)
export function genDdl(d: DdlIn, head: { prjNm: string; at: string }, opt: { only?: Set<string> } = {}): string {
  const tbls = opt.only ? d.tables.filter((t) => opt.only!.has(t.ent_id)) : d.tables
  const nm = (s: string) => (d.ltr === 'LOWER' ? s.toLowerCase() : s.toUpperCase())
  const pg = d.dbms === '0014'
  const out: string[] = [`-- ${line1(head.prjNm)} 물리 모델 DDL — ${DBMS_PRFL[d.dbms].nm}, 생성 ${line1(head.at)}`, '-- 표준 데이터 모델에서 생성(직접 실행 전 DBA 검토)']
  // 저장 후 예약어 목록이 늘었을 수 있어 내려받을 때 다시 점검(P6 이월)
  for (const t of tbls) for (const n of [t.tbl_nm, ...t.cols.map((c) => c.col_nm)]) if (RSV_WORDS.has(n.toUpperCase())) out.push(line1(`-- ⚠ 예약어 이름 ${t.tbl_nm === n ? n : `${t.tbl_nm}.${n}`} : 실행 전 표준용어 물리명을 조정하십시오`))
  // 저장된 기본값도 DEFAULT 에 넣기 전 다시 허용 목록 검사(편집 경로 밖에서 들어온 값 방어)
  for (const t of tbls) for (const c of t.cols) if (c.bsc_val_txt && !bscOk(c.bsc_val_txt, d.dbms)) out.push(line1(`-- ⚠ ${t.tbl_nm}.${c.col_nm} 기본값을 허용 목록 밖이라 생략 : ${c.bsc_val_txt}`))
  if (tbls.some((t) => t.auto_inc_yn === 'Y' && autoIncCol(t, d.fkOf))) out.push(line1(`-- 자동 증가(테이블별 옵션) : 단일 정수 PK ${DBMS_PRFL[d.dbms].autoInc}`))
  out.push('')
  for (const t of tbls) {
    const cols = [...t.cols].sort((a, b) => a.col_seq - b.col_seq)
    const ai = t.auto_inc_yn === 'Y' ? autoIncCol(t, d.fkOf) : null // 대상이 아니면(복합·문자 등) 옵션이 있어도 무시
    const tib = d.dbms === '0013'
    // 자동 증가 칼럼 : PostgreSQL 은 IDENTITY 가 정수형만 받아 INTEGER(9자리 이하)·BIGINT, Oracle 은 NUMBER 그대로. 기본값은 생략
    const colLine = (c: PhyCol) =>
      ai === c && !tib
        ? `  ${nm(c.col_nm).padEnd(30)} ${pg ? ((c.data_len ?? 19) <= 9 ? 'INTEGER' : 'BIGINT') : tpOf(c)} ${pg ? AUTO_INC.pg : AUTO_INC.ora} NOT NULL`
        : `  ${nm(c.col_nm).padEnd(30)} ${tpOf(c)}${c.bsc_val_txt && bscOk(c.bsc_val_txt, d.dbms) ? ` DEFAULT ${c.bsc_val_txt}` : ''}${c.null_yn === 'N' ? ' NOT NULL' : ''}`
    const lines = cols.map(colLine)
    // 시스템 칼럼 4개 — 모델에는 없고 DDL 에서만 맨 끝에 자동 추가(같은 이름 칼럼이 이미 있으면 건너뜀)
    const have = new Set(cols.map((c) => c.col_nm.toUpperCase()))
    const sys = sysCols(d.dbms).filter(([n]) => !have.has(n))
    for (const [n, , tp, dflt] of sys) lines.push(`  ${nm(n).padEnd(30)} ${tp} DEFAULT ${dflt} NOT NULL`)
    const pk = cols.filter((c) => c.pk_yn === 'Y').sort((a, b) => (a.pk_seq ?? 0) - (b.pk_seq ?? 0))
    if (pk.length) lines.push(`  CONSTRAINT ${nm(pkName(d.dbms, t.tbl_nm))} PRIMARY KEY (${pk.map((c) => nm(c.col_nm)).join(', ')})`)
    out.push(`CREATE TABLE ${nm(t.tbl_nm)} (`, lines.join(',\n'), ');')
    if (t.tbl_desc) out.push(`COMMENT ON TABLE ${nm(t.tbl_nm)} IS ${q(t.tbl_desc)};`)
    for (const c of cols) if (c.col_desc) out.push(`COMMENT ON COLUMN ${nm(t.tbl_nm)}.${nm(c.col_nm)} IS ${q(c.col_desc)};`)
    for (const [n, lgc] of sys) out.push(`COMMENT ON COLUMN ${nm(t.tbl_nm)}.${nm(n)} IS ${q(lgc)};`)
    // Tibero : 시퀀스(이름 SQ_테이블명, 식별자 최대 길이 안으로) — 입력 때 시퀀스.NEXTVAL
    if (ai && tib) {
      const sq = nm(`SQ_${t.tbl_nm}`.slice(0, DBMS_PRFL[d.dbms].identMax))
      out.push(`CREATE SEQUENCE ${sq} START WITH 1 INCREMENT BY 1 NOCACHE;`, line1(`-- ${t.tbl_nm}.${ai.col_nm} 입력 때 ${sq}.NEXTVAL 사용(티베로 IDENTITY·DEFAULT 시퀀스 지원 여부 [확인중])`))
    }
    out.push('')
  }
  const byEnt = new Map(d.tables.map((t) => [t.ent_id, t]))
  for (const f of d.fks) {
    if (opt.only && !opt.only.has(f.chld_ent_id)) continue
    if (opt.only && !opt.only.has(f.prnt_ent_id)) {
      out.push(line1(`-- FK 보류 : ${f.fk_nm} — 부모 테이블 미선택(부모 테이블을 함께 선택하거나 따로 추가)`))
      continue
    }
    const pairs = fkPairs(f, byEnt, d)
    const c = byEnt.get(f.chld_ent_id), p = byEnt.get(f.prnt_ent_id)
    if (!c || !p || !pairs.length) {
      out.push(line1(`-- ${f.fk_nm} : 칼럼 쌍을 찾지 못함(관계 FK 상속을 확인하십시오)`))
      continue
    }
    const want = c.cols.filter((x) => x.attr_id && d.fkOf.get(x.attr_id) === f.rel_id).length
    if (pairs.length !== want) out.push(line1(`-- ⚠ ${f.fk_nm} : FK 칼럼 ${want}개 중 ${pairs.length}개만 부모 PK 와 짝지음(원천 속성을 확인하십시오)`))
    const sql = `ALTER TABLE ${nm(c.tbl_nm)} ADD CONSTRAINT ${nm(f.fk_nm)} FOREIGN KEY (${pairs.map((x) => nm(x[0])).join(', ')}) REFERENCES ${nm(p.tbl_nm)} (${pairs.map((x) => nm(x[1])).join(', ')});`
    out.push(pg ? sql : line1(`-- (관계, 물리 FK 미생성 STD-08) ${sql}`))
  }
  return out.join('\n') + '\n'
}

// 물리 정의서 2종(테이블·칼럼) — CSV 는 docs.ts docCsv 재사용
export function phyDocTables(tables: DdlTbl[]): { tbl: DocTable; col: DocTable } {
  return {
    tbl: { title: '테이블정의서', headers: ['테이블명', '설명', '칼럼 수', '주키'], rows: tables.map((t) => [t.tbl_nm, t.tbl_desc ?? '', t.cols.length, t.cols.filter((c) => c.pk_yn === 'Y').map((c) => c.col_nm).join(', ')]) },
    col: {
      title: '칼럼정의서',
      headers: ['테이블명', '순서', '칼럼명', '설명', '데이터타입', 'NULL', '기본값', 'PK', '시스템'],
      rows: tables.flatMap((t) => [...t.cols].sort((a, b) => a.col_seq - b.col_seq).map((c) => [t.tbl_nm, c.col_seq, c.col_nm, c.col_desc ?? '', tpOf(c), c.null_yn, c.bsc_val_txt ?? '', c.pk_yn === 'Y' ? (c.pk_seq ?? 1) : '', c.sys_col_yn])),
    },
  }
}
